catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || newValue == '')
        return;

    // Allows integers and decimal numbers only
    var regex = /^\d+(\.\d+)?$/;

    if (!regex.test(newValue)) {
        g_form.showFieldMsg(
            'u_course_fee', // Replace with your variable name
            'Only numeric decimal values are allowed.',
            'error'
        );

        g_form.clearValue('u_course_fee'); // Replace with your variable name
    }
}
